/*
 *  SPDX-License-Identifier: GPL-3.0-or-later
 *  Copyright (C) 2019-2022, respective authors of MCFM.
 */

#include "ggZZcapture.hpp"

#include <cmath>
#include <complex>
#include <cstddef>
#include <string>
#include <FArray.hpp>
#include <constants_mod.hpp>
#include <ZZclabels_mod.hpp>
#include <ZZdlabels_mod.hpp>
#include <first_mod.hpp>
#include <ggZZ_mod.hpp>

using namespace constants_mod;
using namespace ZZclabels_mod;
using namespace ZZdlabels_mod;
using namespace first_mod;
using namespace ggZZ_mod;

// This is called from within the coefficient-computing routines;
// captures m^0, m^2 and m^4 parts of the coefficient and stores
// in a common block
void ggZZcapture(const std::string& label, int h34, int h56,
                 int j1, int j2, int j3, int j4, int j5, int j6,
                 std::complex<double>& amp0,
                 std::complex<double>& amp2,
                 std::complex<double>& amp4) {

  const int imt0 = 1, imt2 = 2, imt4 = 3;
  const int ipp = 1, imp = 2;
  int htag, ltag = 0, itag = 0;

  // Fortran trim(label): drop trailing blanks
  const std::string trimlabel = label.substr(0, label.find_last_not_of(' ') + 1);

  if (first) {
    for (std::size_t i = 0; i < res.ni * res.nj * res.nk * res.nl; i++) {
      res.data[i] = czip;
    }
    first = false;
  }

  htag = -1;

  // Canonical permutation:  1 2 3 4 5 6
  if ((j1 == 1) && (j2 == 2) && (j3 == 3)
      && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimlabel == "1x2") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_2;
    }
    if ((trimlabel == "1x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_2;
    }
    if ((trimlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_34;
    }
    if ((trimlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_34;
    }
    if ((trimlabel == "12x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimlabel == "12x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimlabel == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimlabel == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimlabel == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimlabel == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimlabel == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_2_1_34;
    }
    // label(1:5) / label(6:6): Fortran substrings of the untrimmed string
    if ((label.size() >= 5) && (label.compare(0, 5, "bubmp") == 0)
        && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 2;
      itag = static_cast<int>(label[5]) - static_cast<int>('0');
    }
    if ((label.size() >= 5) && (label.compare(0, 5, "bubpp") == 0)
        && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 2;
      itag = static_cast<int>(label[5]) - static_cast<int>('0');
    }
  }

  // Permute 1 and 2:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 3)
      && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimlabel == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimlabel == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  // Permute 3,4 and 5,6:  1 2 5 6 3 4
  if ((j1 == 1) && (j2 == 2) && (j3 == 5)
      && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimlabel == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_2_34;
    }
  }

  // Permute 1,3,4 and 2,5,6:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 5)
      && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  if (htag < 0) {
    return;
  }

  // assign results
  res(htag, ltag, itag, imt0) = amp0;   // @coverage-probe
  res(htag, ltag, itag, imt2) = amp2;
  res(htag, ltag, itag, imt4) = amp4;

  if (std::abs(res(htag, ltag, itag, imt0)) < 1e-8)
    res(htag, ltag, itag, imt0) = czip;
  if (std::abs(res(htag, ltag, itag, imt2)) < 1e-8)
    res(htag, ltag, itag, imt2) = czip;
  if (std::abs(res(htag, ltag, itag, imt4)) < 1e-8)
    res(htag, ltag, itag, imt4) = czip;

  return;
}

extern "C" {

  void ggZZcapture_wrapper(const char* label, int h34, int h56,
                           int j1, int j2, int j3, int j4, int j5, int j6,
                           std::complex<double>& amp0,
                           std::complex<double>& amp2,
                           std::complex<double>& amp4) {

    ggZZcapture(std::string(label), h34, h56, j1, j2, j3, j4, j5, j6,
                amp0, amp2, amp4);

  }

}
